  ('6d96b3ac-95be-5dcd-8ecb-ff32b5b80394', null, (select id from public.skills where slug = 'write-g10-argument-writing'), null, 'hard',
   $q$Which statement best explains how sentence (5) strengthens the argument in a way that sentence (4) does not?$q$, $q$[{"text":"It provides a larger and more reliable sample of players than the clinic's study.","is_correct":false,"misconception_token":"misreads-evidence"},{"text":"It answers the coaches' objection that pitch limits would make games less fair.","is_correct":false,"misconception_token":"misidentifies-function"},{"text":"It proves that high pitch counts alone caused every elbow injury in the league.","is_correct":false,"misconception_token":"overstates-evidence"},{"text":"It shows that the risk found in the study is already affecting players in Lakemont's own league.","is_correct":true}]$q$::jsonb, $q$It shows that the risk found in the study is already affecting players in Lakemont's own league.$q$, $q$Sentence (4) gives general research, while sentence (5) shows the problem happening locally, which makes the claim feel urgent for this league. Two injured players is a much smaller sample than 1,200, so sentence (5) is not stronger for its size.$q$, 'draft', '8bc39fcc-09ec-5061-a577-6aac479d141c')
