  ('9948bea1-37c1-5125-9ebd-4b2bef41f3a8', null, (select id from public.skills where slug = 'write-g10-argument-writing'), null, 'easy',
   $q$Which sentence would best replace sentence (2) as a precise statement of the writer's claim?$q$, $q$[{"text":"Pell Harbor High should add a required four-week swimming unit to ninth-grade physical education.","is_correct":true},{"text":"Swimming might be something that some students could think about learning.","is_correct":false,"misconception_token":"hedged-no-position"},{"text":"Water covers most of the surface of the planet that we live on.","is_correct":false,"misconception_token":"too-general"},{"text":"Every student in the state should be required to become a certified lifeguard.","is_correct":false,"misconception_token":"overstated-claim"}]$q$::jsonb, $q$Pell Harbor High should add a required four-week swimming unit to ninth-grade physical education.$q$, $q$The correct choice states a specific, arguable position that fits the survey and the plan for using the pool. Requiring every student in the state to be a lifeguard goes far beyond what the evidence about one school supports.$q$, 'draft', '1b5b026f-499d-58f0-890c-74bbe3061ad8')
