  ('40d54cc7-1c9d-591c-b0b3-096dbcb342e8', null, (select id from public.skills where slug = 'write-g10-argument-writing'), null, 'medium',
   $q$How do sentences (11) and (12) strengthen the argument?$q$, $q$[{"text":"They concede that replanting is a better choice than treatment.","is_correct":false,"misconception_token":"confuses-concession-with-reversal"},{"text":"They provide new evidence about how quickly the insect is spreading.","is_correct":false,"misconception_token":"misreads-function"},{"text":"They address an alternate solution and explain why it would not protect the streams in time.","is_correct":true},{"text":"They restate the claim from sentence (3) using different words.","is_correct":false,"misconception_token":"misidentifies-structure"}]$q$::jsonb, $q$They address an alternate solution and explain why it would not protect the streams in time.$q$, $q$Sentence (11) presents replanting as an alternative, and sentence (12) shows why it falls short. The word "however" in sentence (12) makes clear that the writer does not accept replanting as the better choice.$q$, 'draft', 'df3f57e2-4c90-55ba-8db2-54649a4d7cd1')
